def hashear_contrasenias_heredadas(apps, schema_editor):
    """Convierte las contraseñas en texto plano de la base actual en hashes.

    Usa el modelo histórico, así que no depende del código de la app.
    Una cuenta sin contraseña queda con una contraseña inutilizable (no puede entrar).
    """
    Usuario = apps.get_model('core', 'Usuario')
    for usuario in Usuario.objects.only('id', 'contrasenia').iterator():
        valor = usuario.contrasenia or ''
        try:
            identify_hasher(valor)
            continue  # ya es un hash
        except ValueError:
            pass
        nuevo = make_password(valor) if valor else make_password(None)
        Usuario.objects.filter(pk=usuario.pk).update(contrasenia=nuevo)


